public class SseWebClientWebFluxServerIT {

    private static final Logger logger = LoggerFactory.getLogger(SseWebClientWebFluxServerIT.class);

    private static final JacksonMcpJsonMapper jsonMapper = new JacksonMcpJsonMapper(new ObjectMapper());

    private final ApplicationContextRunner serverContextRunner = new ApplicationContextRunner().withConfiguration(AutoConfigurations.of(McpServerAutoConfiguration.class, McpServerObjectMapperAutoConfiguration.class, ToolCallbackConverterAutoConfiguration.class, McpServerSseWebFluxAutoConfiguration.class));

    private final ApplicationContextRunner clientApplicationContext = new ApplicationContextRunner().withConfiguration(AutoConfigurations.of(McpToolCallbackAutoConfiguration.class, McpClientAutoConfiguration.class, McpClientAnnotationScannerAutoConfiguration.class, SseWebFluxTransportAutoConfiguration.class));

    @Test
    void clientServerCapabilities() {
        int serverPort = TestSocketUtils.findAvailableTcpPort();
        this.serverContextRunner.withUserConfiguration(TestMcpServerConfiguration.class).// @formatter:off
        withPropertyValues("spring.ai.mcp.server.sse-endpoint=/sse", "spring.ai.mcp.server.base-url=http://localhost:" + serverPort, "spring.ai.mcp.server.name=test-mcp-server", "spring.ai.mcp.server.keep-alive-interval=1s", // @formatter:on
        "spring.ai.mcp.server.version=1.0.0").run(serverContext -> {
            // Verify all required beans are present
            assertThat(serverContext).hasSingleBean(WebFluxSseServerTransportProvider.class);
            assertThat(serverContext).hasSingleBean(RouterFunction.class);
            assertThat(serverContext).hasSingleBean(McpSyncServer.class);
            // Verify server properties are configured correctly
            McpServerProperties properties = serverContext.getBean(McpServerProperties.class);
            assertThat(properties.getName()).isEqualTo("test-mcp-server");
            assertThat(properties.getVersion()).isEqualTo("1.0.0");
            // assertThat(properties.getMcpEndpoint()).isEqualTo("/mcp");
            var httpServer = startHttpServer(serverContext, serverPort);
            this.clientApplicationContext.withUserConfiguration(TestMcpClientConfiguration.class).// @formatter:off
            withPropertyValues("spring.ai.mcp.client.sse.connections.server1.url=http://localhost:" + serverPort, // @formatter:on
            "spring.ai.mcp.client.initialized=false").run(clientContext -> {
                McpSyncClient mcpClient = getMcpSyncClient(clientContext);
                assertThat(mcpClient).isNotNull();
                var initResult = mcpClient.initialize();
                assertThat(initResult).isNotNull();
                // TOOLS / SAMPLING / ELICITATION
                // tool list
                assertThat(mcpClient.listTools().tools()).hasSize(2);
                assertThat(mcpClient.listTools().tools()).contains(Tool.builder().name("tool1").description("tool1 description").inputSchema(jsonMapper, """
                    {
                    	"": "http://json-schema.org/draft-07/schema#",
                    	"type": "object",
                    	"properties": {}
                    }
                    """).build());
                // Call a tool that sends progress notifications
                CallToolRequest toolRequest = CallToolRequest.builder().name("tool1").arguments(Map.of()).progressToken("test-progress-token").build();
                CallToolResult response = mcpClient.callTool(toolRequest);
                assertThat(response).isNotNull();
                assertThat(response.isError()).isNull();
                String responseText = ((TextContent) response.content().get(0)).text();
                assertThat(responseText).contains("CALL RESPONSE");
                assertThat(responseText).contains("Response Test Sampling Message with model hint OpenAi");
                assertThat(responseText).contains("ElicitResult");
                // TOOL STRUCTURED OUTPUT
                // Call tool with valid structured output
                CallToolResult calculatorToolResponse = mcpClient.callTool(new McpSchema.CallToolRequest("calculator", Map.of("expression", "2 + 3")));
                assertThat(calculatorToolResponse).isNotNull();
                assertThat(calculatorToolResponse.isError()).isFalse();
                assertThat(calculatorToolResponse.structuredContent()).isNotNull();
                assertThat(calculatorToolResponse.structuredContent()).asInstanceOf(map(String.class, Object.class)).containsEntry("result", 5.0).containsEntry("operation", "2 + 3").containsEntry("timestamp", "2024-01-01T10:00:00Z");
                net.javacrumbs.jsonunit.assertj.JsonAssertions.assertThatJson(calculatorToolResponse.structuredContent()).when(Option.IGNORING_ARRAY_ORDER).when(Option.IGNORING_EXTRA_ARRAY_ITEMS).isObject().isEqualTo(net.javacrumbs.jsonunit.assertj.JsonAssertions.json("""
                    {"result":5.0,"operation":"2 + 3","timestamp":"2024-01-01T10:00:00Z"}"""));
                // PROGRESS
                TestContext testContext = clientContext.getBean(TestContext.class);
                assertThat(testContext.progressLatch.await(5, TimeUnit.SECONDS)).as("Should receive progress notifications in reasonable time").isTrue();
                assertThat(testContext.progressNotifications).hasSize(3);
                Map<String, McpSchema.ProgressNotification> notificationMap = testContext.progressNotifications.stream().collect(Collectors.toMap(n -> n.message(), n -> n));
                // First notification should be 0.0/1.0 progress
                assertThat(notificationMap.get("tool call start").progressToken()).isEqualTo("test-progress-token");
                assertThat(notificationMap.get("tool call start").progress()).isEqualTo(0.0);
                assertThat(notificationMap.get("tool call start").total()).isEqualTo(1.0);
                assertThat(notificationMap.get("tool call start").message()).isEqualTo("tool call start");
                // Second notification should be 1.0/1.0 progress
                assertThat(notificationMap.get("elicitation completed").progressToken()).isEqualTo("test-progress-token");
                assertThat(notificationMap.get("elicitation completed").progress()).isEqualTo(0.5);
                assertThat(notificationMap.get("elicitation completed").total()).isEqualTo(1.0);
                assertThat(notificationMap.get("elicitation completed").message()).isEqualTo("elicitation completed");
                // Third notification should be 0.5/1.0 progress
                assertThat(notificationMap.get("sampling completed").progressToken()).isEqualTo("test-progress-token");
